216→/**
217→ * Create a new DeviceEntry with all fields populated.
218→ *
219→ * Helper that constructs a complete entry for the registry.
220→ *
221→ * @param params.deviceKeypair - Device's Ed25519 keypair with device ID
222→ * @param params.deviceInfo - Device metadata from detectDeviceInfo + IP hash
223→ * @param params.status - Authorization status ('authorized' for first device, 'pending' for subsequent)
224→ * @returns Complete DeviceEntry ready to add to the registry
225→ */
226→export function createEmptyDeviceEntry(params: {
227→  deviceKeypair: DeviceKeypair;
228→  deviceInfo: {
229→    name: string;
230→    platform: DevicePlatform;
231→    appVersion: string;
232→    deviceModel: string;
233→    ipHash: string;
234→  };
235→  status: 'authorized' | 'pending';
236→}): DeviceEntry {
237→  const now = Date.now();
238→
239→  return {
240→    deviceId: params.deviceKeypair.deviceId,
241→    publicKey: bytesToHex(params.deviceKeypair.publicKey),
242→    name: params.deviceInfo.name,
243→    platform: params.deviceInfo.platform,
244→    appVersion: params.deviceInfo.appVersion,
245→    deviceModel: params.deviceInfo.deviceModel,
246→    ipHash: params.deviceInfo.ipHash,
247→    status: params.status,
248→    createdAt: now,
249→    lastSeenAt: now,
250→    revokedAt: null,
251→    revokedBy: null,
252→  };
253→}
