 4→
 5→/**
 6→ * Terminal-style ASCII art for empty state using box-drawing characters.
 7→ * Shows a mini terminal window with `ls -la` returning empty results.
 8→ */
 9→const terminalArt = `\u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510
10→\u2502 $ ls -la             \u2502
11→\u2502 total 0              \u2502
12→\u2502 $ \u2588                  \u2502
13→\u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518`;
14→
15→type EmptyStateProps = {
16→  folderId: string;
17→};
18→
19→export function EmptyState({ folderId }: EmptyStateProps) {
20→  const { handleFileDrop, isUploading } = useDropUpload();
21→  const [error, setError] = useState<string | null>(null);
22→
23→  const handleDrop = useCallback(
24→    async (acceptedFiles: File[], rejectedFiles: FileRejection[]) => {
25→      setError(null);
26→
27→      if (rejectedFiles.length > 0) {
28→        const oversized = rejectedFiles.filter((r) =>
29→          r.errors.some((e) => e.code === 'file-too-large')
30→        );
31→        if (oversized.length > 0) {
32→          setError(`Files exceed 100MB limit: ${oversized.map((r) => r.file.name).join(', ')}`);
33→          return;
34→        }
35→        setError('Some files were rejected');
36→        return;
37→      }
38→
39→      if (acceptedFiles.length === 0) return;
40→
41→      await handleFileDrop(acceptedFiles, folderId);
42→    },
43→    [handleFileDrop, folderId]
44→  );
45→
46→  const { getRootProps, getInputProps, isDragActive } = useDropzone({
47→    onDrop: handleDrop,
48→    noClick: false,
49→    multiple: true,
50→    maxSize: MAX_FILE_SIZE,
51→  });
52→
53→  const classes = ['empty-state'];
54→  if (isDragActive) classes.push('empty-state-drag-active');
55→  if (isUploading) classes.push('empty-state-uploading');
56→
57→  return (
58→    <div {...getRootProps({ className: classes.join(' ') })} data-testid="empty-state">
59→      <input {...getInputProps()} />
60→      <div className="empty-state-content">
61→        <pre className="empty-state-ascii" aria-hidden="true">
62→          {terminalArt}
63→        </pre>
64→        <p className="empty-state-text">
65→          {isUploading ? '// UPLOADING...' : isDragActive ? '// DROP FILES' : '// EMPTY DIRECTORY'}
66→        </p>
67→        <p className="empty-state-hint">drag files here or use --upload</p>
68→      </div>
69→      {error && (
70→        <div className="upload-zone-error" role="alert">
71→          {error}
72→          <button
73→            type="button"
74→            className="upload-zone-error-dismiss"
75→            onClick={(e) => {
76→              e.stopPropagation();
77→              setError(null);
78→            }}
79→            aria-label="Dismiss error"
80→          >
81→            &times;
82→          </button>
83→        </div>
84→      )}
85→    </div>
86→  );
87→}
