import { useCallback, type MouseEvent } from 'react';
import type { BinEntry } from '@cipherbox/crypto';
import { formatBytes } from '../../utils/format';

type BinListItemProps = {
  /** The bin entry to display */
  entry: BinEntry;
  /** Whether this item is currently selected */
  isSelected: boolean;
  /** Days remaining before auto-purge */
  daysLeft: number;
  /** Callback when item is clicked (with modifier key info) */
  onSelect: (
    entryId: string,
    event: { ctrlKey: boolean; shiftKey: boolean; metaKey: boolean }
  ) => void;
  /** Callback when right-click context menu is requested */
  onContextMenu: (event: MouseEvent, entry: BinEntry) => void;
};

/**
 * Format a deletion timestamp as a relative time string.
 */
function formatRelativeTime(timestamp: number): string {
  const diff = Date.now() - timestamp;
  const seconds = Math.floor(diff / 1000);
  const minutes = Math.floor(seconds / 60);
  const hours = Math.floor(minutes / 60);
  const days = Math.floor(hours / 24);

  if (seconds < 60) return 'just now';
  if (minutes < 60) return `${minutes}m ago`;
  if (hours < 24) return `${hours}h ago`;
  if (days === 1) return '1 day ago';
  return `${days} days ago`;
}

/**
 * Get a terminal-style type indicator based on item type and MIME.
 */
function getItemIcon(entry: BinEntry): string {
  if (entry.itemType === 'folder') return '[DIR]';
  if (!entry.mimeType) return '[FILE]';
  if (entry.mimeType.startsWith('image/')) return '[IMG]';
  if (entry.mimeType.startsWith('video/')) return '[VID]';
  if (entry.mimeType.startsWith('audio/')) return '[AUD]';
  if (entry.mimeType.startsWith('text/')) return '[TXT]';
  if (entry.mimeType === 'application/pdf') return '[PDF]';
  return '[FILE]';
}

/**
 * Single row in the bin list.
 *
 * Displays deleted item with name, original location, deletion date,
 * file size, and days remaining before auto-purge.
 */
export function BinListItem({
  entry,
  isSelected,
  daysLeft,
  onSelect,
  onContextMenu,
}: BinListItemProps) {
  const handleClick = useCallback(
    (e: React.MouseEvent) => {
      onSelect(entry.id, { ctrlKey: e.ctrlKey, shiftKey: e.shiftKey, metaKey: e.metaKey });
    },
    [entry.id, onSelect]
  );

  const handleCheckboxClick = useCallback(
    (e: React.MouseEvent) => {
      e.stopPropagation();
      onSelect(entry.id, { ctrlKey: true, shiftKey: false, metaKey: false });
    },
    [entry.id, onSelect]
  );

  const handleContextMenu = useCallback(
    (e: MouseEvent) => {
      e.preventDefault();
      onContextMenu(e, entry);
    },
    [entry, onContextMenu]
  );

  const sizeDisplay =
    entry.itemType === 'folder' && entry.size === 0 ? 'Folder' : formatBytes(entry.size);

  const remainingText = daysLeft <= 0 ? 'expired' : daysLeft === 1 ? '< 1 day' : `${daysLeft}d`;

  const isWarning = daysLeft <= 3;

  const className = [
    'bin-list-item',
    isSelected ? 'bin-list-item--selected' : '',
    isWarning ? 'bin-list-item--warning' : '',
  ]
    .filter(Boolean)
    .join(' ');

  return (
    <div
      className={className}
      data-testid={`bin-item-${entry.id}`}
      onClick={handleClick}
      onContextMenu={handleContextMenu}
      role="row"
      aria-selected={isSelected}
      tabIndex={0}
      onKeyDown={(e) => {
        if (e.key === 'Enter') {
          e.preventDefault();
          onContextMenu(e as unknown as MouseEvent, entry);
        }
      }}
    >
      <div className="bin-list-item-name" role="gridcell">
        <span
          className="bin-list-item-checkbox"
          onClick={handleCheckboxClick}
          role="checkbox"
          aria-checked={isSelected}
          aria-label={`Select ${entry.name}`}
          tabIndex={-1}
          onKeyDown={(e) => {
            if (e.key === 'Enter' || e.key === ' ') {
              e.preventDefault();
              e.stopPropagation();
              onSelect(entry.id, { ctrlKey: true, shiftKey: false, metaKey: false });
            }
          }}
        >
          {isSelected ? '[x]' : '[ ]'}
        </span>
        <span className="bin-list-item-icon" aria-hidden="true">
          {getItemIcon(entry)}
        </span>
        <span className="bin-list-item-label">{entry.name}</span>
      </div>
      <div className="bin-list-item-path" role="gridcell" title={entry.originalPath}>
        {entry.originalPath}
      </div>
      <div className="bin-list-item-deleted" role="gridcell">
        {formatRelativeTime(entry.deletedAt)}
      </div>
      <div className="bin-list-item-size" role="gridcell">
        {sizeDisplay}
      </div>
      <div
        className={`bin-list-item-remaining ${isWarning ? 'bin-list-item-remaining--warning' : ''}`}
        role="gridcell"
      >
        {remainingText}
      </div>
    </div>
  );
}

/**
 * Terminal-style ASCII art for bin empty state.
 */
const binEmptyArt = `\u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510
\u2502 $ ls ~/bin           \u2502
\u2502 total 0              \u2502
\u2502 $ \u2588                  \u2502
\u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518`;

type BinEmptyStateProps = {
  /** Retention period in days for display */
  retentionDays: number;
};

/**
 * Empty state shown when the recycle bin has no items.
 * Follows the same terminal aesthetic as EmptyState.tsx.
 */
export function BinEmptyState({ retentionDays }: BinEmptyStateProps) {
  return (
    <div className="empty-state bin-empty-state" data-testid="bin-empty-state">
      <div className="empty-state-content">
        <pre className="empty-state-ascii" aria-hidden="true">
          {binEmptyArt}
        </pre>
        <p className="empty-state-text">{'// BIN IS EMPTY'}</p>
        <p className="empty-state-hint">
          deleted items will appear here for {retentionDays} days
        </p>
      </div>
    </div>
  );
}

/**
 * Bin Browser Styles -- Recycle Bin view
 *
 * Extends file-browser.css with bin-specific elements:
 * - 5-column grid layout (Name, Location, Deleted, Size, Time Left)
 * - Warning state for items nearing auto-purge
 * - Destructive Empty Bin button
 * - Bin-specific context menu (Restore, Delete Permanently)
 */

/* ==========================================================================
   Bin Browser Container
   ========================================================================== */

.bin-browser .file-browser-toolbar {
  border-bottom: 1px solid rgb(0 255 128 / 10%);
}

/* Empty Bin destructive button */
.toolbar-btn--destructive {
  color: var(--color-error);
  border-color: var(--color-error);
  background: transparent;
}

.toolbar-btn--destructive:hover:not(:disabled) {
  box-shadow: 0 0 8px rgb(255 0 0 / 20%);
}

.toolbar-btn--destructive:focus-visible {
  outline: 2px solid var(--color-error);
  outline-offset: 1px;
}

.toolbar-btn--destructive:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

/* ==========================================================================
   Bin List Header (5-column grid)
   ========================================================================== */

.bin-list-header {
  display: grid;
  grid-template-columns: 1fr 180px 100px 80px 90px;
  gap: var(--spacing-md);
  padding: var(--spacing-sm) var(--spacing-md);
  border-bottom: var(--border-thickness) solid var(--color-border);
  font-family: var(--font-family-mono);
  font-size: var(--font-size-xs);
  font-weight: var(--font-weight-semibold);
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--color-text-primary);
  background-color: var(--color-background);
}

.bin-column-header {
  display: flex;
  align-items: center;
  background: none;
  border: none;
  padding: 0;
  font: inherit;
  color: inherit;
  text-transform: inherit;
  letter-spacing: inherit;
  cursor: pointer;
  user-select: none;
  white-space: nowrap;
}

.bin-column-header:hover {
  color: var(--color-green-primary);
}

.bin-column-header:focus-visible {
  outline: 1px solid var(--color-green-primary);
  outline-offset: 1px;
}

/* Non-sortable column header */
.bin-column-path {
  cursor: default;
}

.bin-column-path:hover {
  color: inherit;
}

/* ==========================================================================
   Bin List Item (5-column grid matching header)
   ========================================================================== */

.bin-list-item {
  display: grid;
  grid-template-columns: 1fr 180px 100px 80px 90px;
  gap: var(--spacing-md);
  padding: var(--spacing-sm) var(--spacing-md);
  cursor: pointer;
  transition: background-color 0.15s ease;
  border-bottom: var(--border-thickness) solid var(--color-border-dim);
  font-family: var(--font-family-mono);
}

.bin-list-item:last-child {
  border-bottom: none;
}

.bin-list-item:hover {
  background-color: var(--color-green-darker);
}

.bin-list-item:focus-visible {
  outline: 1px solid var(--color-green-primary);
  outline-offset: -1px;
}

.bin-list-item--selected {
  background-color: var(--color-green-darker);
}

.bin-list-item--selected:hover {
  background-color: var(--color-green-darker);
}

/* Warning state for items with <= 3 days remaining */
.bin-list-item--warning {
  border-left: 2px solid var(--color-warning, #f59e0b);
}

/* Name column */
.bin-list-item-name {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
}

.bin-list-item-checkbox {
  display: inline;
  cursor: pointer;
  font-family: var(--font-family-mono);
  font-size: var(--font-size-sm);
  color: var(--color-text-secondary);
  margin-right: 4px;
  flex-shrink: 0;
}

.bin-list-item-checkbox:hover {
  color: var(--color-green-primary);
}

.bin-list-item-checkbox:focus-visible {
  outline: 2px solid var(--color-green-primary);
  outline-offset: 1px;
}

.bin-list-item-icon {
  font-family: var(--font-family-mono);
  font-size: var(--font-size-sm);
  font-weight: var(--font-weight-semibold);
  flex-shrink: 0;
  color: var(--color-text-primary);
}

.bin-list-item-label {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  color: var(--color-text-primary);
  font-size: var(--font-size-sm);
}

/* Original path column */
.bin-list-item-path {
  display: flex;
  align-items: center;
  color: var(--color-text-dim);
  font-size: var(--font-size-xs);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* Deleted date column */
.bin-list-item-deleted {
  display: flex;
  align-items: center;
  color: var(--color-text-secondary);
  font-size: var(--font-size-sm);
}

/* Size column */
.bin-list-item-size {
  display: flex;
  align-items: center;
  color: var(--color-text-secondary);
  font-size: var(--font-size-sm);
}

/* Time remaining column */
.bin-list-item-remaining {
  display: flex;
  align-items: center;
  color: var(--color-text-secondary);
  font-size: var(--font-size-sm);
}

.bin-list-item-remaining--warning {
  color: var(--color-warning, #f59e0b);
  font-weight: var(--font-weight-semibold);
}

/* ==========================================================================
   Bin Context Menu
   ========================================================================== */

.bin-context-menu {
  z-index: 1000;
}

/* ==========================================================================
   Bin Empty State
   ========================================================================== */

.bin-empty-state {
  cursor: default;
}

.bin-empty-state:hover {
  border-color: var(--color-border);
  background-color: transparent;
}

/* ==========================================================================
   Bin Error State
   ========================================================================== */

.bin-error {
  font-family: var(--font-family-mono);
  font-size: 0.85rem;
  color: var(--color-error);
  padding: var(--spacing-md) var(--spacing-lg);
  text-align: center;
  opacity: 0.9;
}

/* ==========================================================================
   Bin Selection Bar
   ========================================================================== */

.bin-selection-bar .toolbar-btn--secondary:first-of-type {
  color: var(--color-green-primary);
  border-color: var(--color-green-dim);
}

